unitDefinition:
{
  "id": "syscheck-unit-definition",
  "version": "0.1",
  "viewType": "REPORT",
  "viewParameters": {
    "system": {
      "browser": {
        "enabled": true,
        "limits": [
          {
            "browser": "chrome",
            "minVersion": "143"
          },
          {
            "browser": "firefox",
            "minVersion": "143"
          },
          {
            "browser": "safari",
            "minVersion": "145",
            "message": "min required version: 145"
          }
        ]
      },
      "os": {
        "enabled": true,
        "limits": [
          {
            "os": "windows",
            "minVersion": "10"
          },
          {
            "os": "ios",
            "minVersion": "15"
          },
          {
            "os": "android",
            "minVersion": "12"
          },
          {
            "os": "macos",
            "minVersion": "12"
          },
          {
            "os": "linux",
            "minVersion": "1"
          }
        ]
      },
      "resolution": {
        "enabled": true,
        "limits": [
          {
            "width": 1200,
            "height": 800
          }
        ]
      },
      "touch": {
        "enabled": true
      },
      "webgl": {
        "enabled": true
      }
    },
    "messages": {
      "title": "Bericht",
